const __pageData = JSON.parse('{"title":"Jack Smith","description":"","frontmatter":{"title":"Jack Smith","created":"2026-08-06T00:00:00.000Z","updated":"2026-08-06T00:00:00.000Z","type":"entity","tags":["prosecutor","special-counsel","2020-election","indictment","lawfare"],"sources":["raw/are-jack-smith-and-fani-willis-in.md","raw/badlands-brief-245.md","raw/badlands-brief-695.md","raw/badlands-brief-739.md","raw/badlands-brief-c7b.md","raw/badlands-brief-e60.md","raw/badlands-brief.md","raw/badlands-news-blast.md","raw/badlands-news-brief-053.md","raw/badlands-news-brief-066.md","raw/badlands-news-brief-07f.md","raw/badlands-news-brief-08a.md","raw/badlands-news-brief-08c.md","raw/badlands-news-brief-09e.md","raw/badlands-news-brief-0ec.md","raw/badlands-news-brief-109.md","raw/badlands-news-brief-228.md","raw/badlands-news-brief-2a0.md","raw/badlands-news-brief-34a.md","raw/badlands-news-brief-363.md","raw/badlands-news-brief-360.md","raw/badlands-news-brief-505.md","raw/badlands-news-brief-525.md","raw/badlands-news-brief-5a7.md","raw/badlands-news-brief-59b.md","raw/badlands-news-brief-617.md","raw/badlands-news-brief-656.md","raw/badlands-news-brief-6bc.md","raw/badlands-news-brief-6b6.md","raw/badlands-news-brief-6b1.md","raw/badlands-news-brief-7ad.md","raw/badlands-news-brief-855.md","raw/badlands-news-brief-88b.md","raw/badlands-news-brief-89f.md","raw/badlands-news-brief-8ba.md","raw/badlands-news-brief-8c5.md"],"confidence":"medium"},"headers":[],"relativePath":"entities/jack-smith.md","filePath":"entities/jack-smith.md","lastUpdated":null}');
